function makeSalt(){const bytes=crypto.getRandomValues(new Uint8Array(16));return [...bytes].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function hashPassword(password,salt){let value=password;for(let i=0;i<1200;i++)value=await sha256(salt+':'+value);return value}
