function userId(name){return encodeURIComponent(String(name||'').trim().toLowerCase()).replace(/\./g,'%2E')}
function privateThreadId(a,b){return [a,b].sort().map(v=>encodeURIComponent(v)).join('__')}
function clearChatListeners(){chatCleanup.splice(0).forEach(fn=>{try{fn()}catch{}})}
