function renderContacts(){if(!user)return;const me=currentAccountId();const entries=Object.entries(knownUsers).filter(([id,data])=>id!==me&&data?.name).sort((a,b)=>{const ao=onlineUserIds.has(a[0])?1:0,bo=onlineUserIds.has(b[0])?1:0;return bo-ao||safeText(a[1].name).localeCompare(safeText(b[1].name),'id')});els.contactsList.innerHTML='';if(!entries.length){els.contactsList.innerHTML='<div class="contact-empty">Belum ada pengguna lain. Nama yang pernah masuk akan tampil di sini.</div>';return}entries.forEach(([id,data])=>{const btn=document.createElement('button');btn.className='contact'+(currentView.type==='private'&&currentView.peer?.id===id?' active':'');btn.type='button';const avatar=document.createElement('div');avatar.className='avatar';avatar.textContent=initials(data.name);const dot=document.createElement('i');dot.className='contact-dot'+(onlineUserIds.has(id)?' online':'');avatar.appendChild(dot);const copy=document.createElement('div');copy.className='contact-copy';const name=document.createElement('strong');name.textContent=data.name;const status=document.createElement('small');status.textContent=onlineUserIds.has(id)?'Online · klik untuk japri':'Offline · klik untuk japri';copy.append(name,status);const badge=document.createElement('span');const unread=Number(unreadPrivate[id]||0);badge.className='contact-badge'+(unread?' unread':'');badge.textContent=unread?(unread>99?'99+':String(unread)):'JAPRI';btn.append(avatar,copy,badge);btn.onclick=()=>openPrivateChat(id,data.name);els.contactsList.appendChild(btn)})}
