function subscribeMessages(){const previousTyping=refs.typing;clearTimeout(typingTimer);typingTimer=null;if(previousTyping)previousTyping.remove().catch(()=>{});clearChatListeners();clearSessionUI();const base=`rooms/${currentRoomId}`,threadId=currentView.type==='private'?privateThreadId(currentAccountId(),currentView.peer.id):null;refs.messages=threadId?db.ref(`${base}/privateThreads/${threadId}/messages`):db.ref(`${base}/messages`);const typingRoot=threadId?db.ref(`${base}/privateThreads/${threadId}/typing`):db.ref(`${base}/typing`);refs.typing=typingRoot.child(encodeURIComponent(user.sessionId));refs.typing.onDisconnect().remove();listenChat(typingRoot,'value',snap=>{const names=[];snap.forEach(child=>{const val=child.val();if(child.key!==encodeURIComponent(user.sessionId)&&val?.name)names.push(val.name)});els.typing.classList.toggle('hidden',!names.length);els.typingText.textContent=names.length?`${names.slice(0,2).join(', ')} sedang mengetik`:'Seseorang sedang mengetik'});const query=refs.messages.orderByChild('timestamp').startAt(Date.now()-MESSAGE_TTL_MS).limitToLast(150);let knownMessageIds=new Set(),messagesReady=false;listenChat(query,'value',snap=>{const nextIds=new Set(),items=[];snap.forEach(child=>{const data=child.val();if(data){nextIds.add(child.key);items.push([child.key,data])}});els.messages.querySelectorAll('[data-id]').forEach(node=>node.remove());if(!items.length&&!$('welcome'))els.messages.insertAdjacentHTML('afterbegin','<div id="welcome" class="welcome"><div class="welcome-icon">'+(currentView.type==='private'?'✉':'✦')+'</div><h2>'+(currentView.type==='private'?'Mulai japri':'Awal percakapan')+'</h2><p>'+(currentView.type==='private'?'Pesan ini hanya tampil untuk kamu dan '+safeText(currentView.peer.name)+'.':'Pesan otomatis dihapus setelah tersimpan selama 24 jam.')+'</p></div>');items.forEach(([id,data])=>renderMessage(id,data,messagesReady&&!knownMessageIds.has(id)));knownMessageIds=nextIds;messagesReady=true;resetIdle();scrollBottom()})}
