function openPrivateChat(id,name){if(id===currentAccountId())return;if(currentView.type==='public'){roomLastRead[currentRoomId]=Date.now();unreadRooms[currentRoomId]=0}unreadPrivate[id]=0;updateDocumentTitle();currentView={type:'private',peer:{id,name}};setConversationHeader();subscribeMessages();if(latestRoomsSnapshot)renderRoomSidebar(latestRoomsSnapshot);closeSidebar();els.messageInput.focus()}
function subscribePrivateInbox(){const me=currentAccountId(),root=db.ref(`rooms/${currentRoomId}/privateThreads`);inboxReady=false;inboxLatest={};listen(root,'value',snap=>{const next={};snap.forEach(thread=>{let latest=null;thread.child('messages').forEach(message=>{const value=message.val();if(value&&(!latest||Number(value.timestamp||0)>Number(latest.timestamp||0)))latest=value});if(!latest||latest.privateTo!==me||latest.userId===me)return;const senderId=latest.userId;const timestamp=Number(latest.timestamp||0);next[thread.key]=timestamp;const previous=Number(inboxLatest[thread.key]||0);const isOpen=currentView.type==='private'&&currentView.peer?.id===senderId;if(inboxReady&&timestamp>previous&&!isOpen){unreadPrivate[senderId]=Number(unreadPrivate[senderId]||0)+1;notifyIncoming(latest.name,latest.type==='image'?'📷 Foto':latest.text,true);showToast(`Japri baru dari ${safeText(latest.name)}`)}else if(isOpen)unreadPrivate[senderId]=0});inboxLatest=next;inboxReady=true;updateDocumentTitle();renderContacts()})}
