async function ensureDefaultRoom(){const snap=await db.ref('appConfig/rooms/'+DEFAULT_ROOM_ID).once('value');if(!snap.exists()||!snap.val()?.codeHash)throw new Error('Konfigurasi Ruang Umum belum tersedia di Firebase.')}
async function resolveRoomByCode(code){await ensureDefaultRoom();const wanted=await sha256(code),snap=await db.ref('appConfig/rooms').once('value');let found=null;snap.forEach(child=>{const data=child.val()||{};if(data.active!==false&&data.codeHash===wanted)found={id:child.key,name:data.name||child.key}});return found}
async function getAdminCodeHash(){const snap=await db.ref('appConfig/adminCodeHash').once('value');return snap.val()||DEFAULT_ADMIN_CODE_HASH}
async function claimActiveSession(id,sessionId,name){const ref=db.ref('appConfig/activeSessions/'+id);const result=await ref.transaction(current=>{if(current&&current.sessionId&&current.sessionId!==sessionId)return;return {sessionId,name:safeText(name).slice(0,24),startedAt:current?.startedAt||firebase.database.ServerValue.TIMESTAMP,lastSeen:firebase.database.ServerValue.TIMESTAMP}});if(result.committed){activeSessionRef=ref;ref.onDisconnect().remove()}return result.committed}
async function releaseActiveSession(){const ref=activeSessionRef;if(!ref||!user?.sessionId)return;const ownedSession=user.sessionId;try{await ref.transaction(current=>current?.sessionId===ownedSession?null:undefined)}finally{activeSessionRef=null}}
async function login(name,password,code){if(!name)throw new Error('ID atau username wajib diisi.');const wantsAdmin=name.trim().toLowerCase()===ADMIN_NAME;let account;
  if(wantsAdmin){if(!password)throw new Error('Password admin wajib diisi.');if(await sha256(password)!==await getAdminCodeHash())throw new Error('ID atau password admin salah.');const roomSnap=await db.ref('appConfig/rooms/'+DEFAULT_ROOM_ID).once('value'),room=roomSnap.val();if(!room?.codeHash)throw new Error('Konfigurasi Ruang Umum belum tersedia di Firebase.');currentRoomId=DEFAULT_ROOM_ID;currentRoomName=room.name||DEFAULT_ROOM_NAME;account={accountId:accountId(ADMIN_NAME),username:'admin',status:'approved',role:'admin',roomId:currentRoomId,roomName:currentRoomName}}
  else{if(!password||!code)throw new Error('Username, password, dan kode ruang wajib diisi.');const room=await resolveRoomByCode(code);if(!room)throw new Error('Kode ruang tidak cocok atau room dinonaktifkan.');currentRoomId=room.id;currentRoomName=room.name;const snap=await db.ref('appConfig/accounts/'+accountId(name)).once('value');account=snap.val();if(!account)throw new Error('Akun belum terdaftar. Silakan daftar lebih dulu.');if(account.usernameLower!==name.trim().toLowerCase())throw new Error('Username tidak cocok.');if(account.status==='pending')throw new Error('Akun masih menunggu ACC admin.');if(account.status!=='approved')throw new Error('Akun ditolak atau dinonaktifkan admin.');if(await hashPassword(password,account.salt)!==account.passwordHash)throw new Error('Password salah.')}
  const base='rooms/'+currentRoomId,settingsSnap=await db.ref(base+'/settings').once('value');appSettings={...appSettings,...(settingsSnap.val()||{})};const uid=account.accountId;const banSnap=await db.ref(base+'/bannedUsers/'+uid).once('value');if(banSnap.exists()&&!wantsAdmin)throw new Error('Akun ini diblokir oleh admin.');if(appSettings.maintenance&&!wantsAdmin)throw new Error('Room sedang dalam mode maintenance. Coba lagi nanti.');const nextSessionId=crypto.randomUUID?.()||String(Date.now());if(!await claimActiveSession(uid,nextSessionId,account.username))throw new Error('Akun sedang aktif di perangkat lain. Logout dari perangkat lama terlebih dahulu.');user={name:account.username.slice(0,24),accountId:uid,roomId:currentRoomId,roomName:currentRoomName,isAdmin:wantsAdmin,sessionId:nextSessionId};localStorage.setItem('nusa_chat_user',JSON.stringify(user));els.loginPage.classList.add('hidden');els.chatApp.classList.remove('hidden');$('userName').textContent=user.name;$('userAvatar').textContent=initials(user.name);$('clearChatBtn').classList.toggle('hidden',!isAdmin());$('membersBtn').classList.toggle('hidden',!isAdmin());$('adminPanelBtn').classList.toggle('hidden',!isAdmin());requestNotificationPermission();try{await startChat()}catch(err){await releaseActiveSession().catch(()=>{});throw err}}
async function startChat(){cleanupSession();isLoggingOut=false;clearSessionUI();latestRoomsSnapshot=null;currentView={type:'public',peer:null};roomLastRead[currentRoomId]=Date.now();unreadRooms[currentRoomId]=0;activeSessionRef=db.ref('appConfig/activeSessions/'+currentAccountId());activeSessionRef.onDisconnect().remove();listen(activeSessionRef,'value',snap=>{const active=snap.val();if(!isLoggingOut&&(!active||active.sessionId!==user?.sessionId))logout('Sesi akun ini sudah tidak aktif. Silakan login kembali.')});const roomsRef=db.ref('appConfig/rooms');listen(roomsRef,'value',snap=>{latestRoomsSnapshot=snap;subscribeRoomInboxes(snap);renderRoomSidebar(snap)});const base=`rooms/${currentRoomId}`;refs.messages=db.ref(`${base}/messages`);refs.presence=db.ref(`${base}/presence/${encodeURIComponent(user.sessionId)}`);refs.kick=db.ref(`${base}/kicks/${encodeURIComponent(user.sessionId)}`);await refs.kick.remove();refs.presence.set({name:user.name,userId:currentAccountId(),at:firebase.database.ServerValue.TIMESTAMP});refs.presence.onDisconnect().remove();
  refs.users=db.ref(`${base}/users`);refs.settings=db.ref(`${base}/settings`);refs.banned=db.ref(`${base}/bannedUsers`);if(isAdmin()){refs.accounts=db.ref('appConfig/accounts');listen(refs.accounts,'value',updateAdminPendingBadge)}else{refs.account=db.ref('appConfig/accounts/'+currentAccountId());listen(refs.account,'value',snap=>{const account=snap.val();if(!account||account.status!=='approved')logout('Akun kamu telah dihapus atau dinonaktifkan admin.')})}listen(refs.settings,'value',snap=>{appSettings={...appSettings,...(snap.val()||{})};applyRoomSettings();if(appSettings.maintenance&&!isAdmin())logout('Room masuk mode maintenance.');});listen(refs.banned.child(currentAccountId()),'value',snap=>{if(snap.exists()&&!isAdmin())logout('Akun kamu telah diblokir oleh admin.')});await refs.users.child(currentAccountId()).update({name:user.name,lastSeen:firebase.database.ServerValue.TIMESTAMP});await cleanupExpiredMessages();cleanupTimer=setInterval(cleanupExpiredMessages,CLEANUP_INTERVAL_MS);currentView={type:'public',peer:null};subscribeMessages();subscribePrivateInbox();
  listen(refs.kick,'value',snap=>{const kick=snap.val();if(!kick||isLoggingOut)return;refs.kick.remove().catch(()=>{});logout(kick.reason||'Kamu telah dikeluarkan dari ruang oleh admin.')});
  const presence=db.ref(`${base}/presence`);let presenceReady=false;
  listen(presence,'child_added',snap=>{if(presenceReady&&snap.key!==encodeURIComponent(user.sessionId)){const member=snap.val();showPresenceEvent(member?.name,'join')}});
  listen(presence,'child_removed',snap=>{if(presenceReady&&snap.key!==encodeURIComponent(user.sessionId)){const member=snap.val();showPresenceEvent(member?.name,'leave')}});
  listen(presence,'value',snap=>{onlineUserIds=new Set();snap.forEach(child=>{const val=child.val();if(val?.userId)onlineUserIds.add(val.userId);else if(val?.name)onlineUserIds.add(userId(val.name))});const count=onlineUserIds.size;if($('onlineCount'))$('onlineCount').textContent=count;els.sideOnline.textContent=count;if(latestRoomsSnapshot)renderRoomSidebar(latestRoomsSnapshot);if(isAdmin())renderMembers(snap);renderContacts();setConversationHeader();if(!presenceReady)presenceReady=true});
  listen(refs.users,'value',snap=>{knownUsers=snap.val()||{};renderContacts()});
  const connected=db.ref('.info/connected');listen(connected,'value',snap=>setConnected(snap.val()===true));resetIdle();els.messageInput.focus()
}

function addAdminLog(text){adminLogs.unshift(new Date().toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})+' · '+text);adminLogs=adminLogs.slice(0,30);const box=$('adminLog');if(box)box.innerHTML=adminLogs.map(x=>'<div>'+safeText(x)+'</div>').join('')}
function applyRoomSettings(){const allow=appSettings.allowImages!==false;$('photoBtn').classList.toggle('hidden',!allow);els.messageInput.maxLength=Math.max(100,Math.min(3000,Number(appSettings.maxLength)||1000));if($('maintenanceToggle'))$('maintenanceToggle').checked=!!appSettings.maintenance;if($('imagesToggle'))$('imagesToggle').checked=allow;if($('ttlSelect'))$('ttlSelect').value=String(Number(appSettings.ttlHours)||24);if($('maxLengthInput'))$('maxLengthInput').value=String(Number(appSettings.maxLength)||1000)}
async function setAccountStatus(id,status,name){if(!isAdmin())return;const ref=db.ref('appConfig/accounts/'+id);if(status==='approved'){await ref.update({status:'approved',reviewedBy:currentAccountId(),reviewedAt:firebase.database.ServerValue.TIMESTAMP});addAdminLog('Menyetujui '+safeText(name));showToast('Akun disetujui dan permintaan dihapus dari antrean.')}else{await ref.remove();addAdminLog('Menolak dan menghapus pendaftaran '+safeText(name));showToast('Pendaftaran ditolak dan dihapus.')}await refreshAdminPanel()}
