async function deleteRoom(id,name){if(!isAdmin()||id===DEFAULT_ROOM_ID)return showToast('Ruang Umum tidak dapat dihapus.');if(id===currentRoomId)return showToast('Pindah ke room lain sebelum menghapus room ini.');if(!confirm('Hapus room '+safeText(name)+' beserta seluruh chat di room ini?'))return;const typed=prompt('Ketik nama room untuk konfirmasi: '+safeText(name));if(typed!==safeText(name))return showToast('Konfirmasi nama room tidak cocok.');const updates={};updates['appConfig/rooms/'+id]=null;updates['rooms/'+id]=null;await db.ref().update(updates);addAdminLog('Menghapus room '+safeText(name));showToast('Room dan seluruh chatnya berhasil dihapus. Akun pengguna tetap aman.');await refreshRoomsAdmin()}
function subscribeRoomInboxes(snap){clearRoomInboxListeners();const activeRoomIds=new Set();snap.forEach(child=>{const room=child.val()||{},roomId=child.key;if(room.active===false)return;activeRoomIds.add(roomId);if(!roomLastRead[roomId])roomLastRead[roomId]=Date.now();const query=db.ref(`rooms/${roomId}/messages`).orderByChild('timestamp').limitToLast(150),handler=messageSnap=>{const isOpen=roomId===currentRoomId&&currentView.type==='public',previous=Number(unreadRooms[roomId]||0);let unread=0,latestIncoming=null;messageSnap.forEach(message=>{const value=message.val()||{},senderId=value.senderId||value.userId;if(Number(value.timestamp||0)>roomLastRead[roomId]&&senderId!==currentAccountId()){unread++;latestIncoming=value}});unreadRooms[roomId]=isOpen?0:unread;if(isOpen)roomLastRead[roomId]=Date.now();if(!isOpen&&unread>previous&&latestIncoming){notifyIncoming(latestIncoming.name,latestIncoming.type==='image'?'📷 Foto':latestIncoming.text,false);showToast(`Pesan baru di ${safeText(room.name||roomId)}`)}updateDocumentTitle();if(latestRoomsSnapshot)renderRoomSidebar(latestRoomsSnapshot)};query.on('value',handler);roomInboxCleanup.push(()=>query.off('value',handler))});Object.keys(unreadRooms).forEach(roomId=>{if(!activeRoomIds.has(roomId))delete unreadRooms[roomId]});Object.keys(roomLastRead).forEach(roomId=>{if(!activeRoomIds.has(roomId))delete roomLastRead[roomId]})}
function renderRoomSidebar(snap){const list=$('roomGroupList');if(!list)return;list.innerHTML='';snap.forEach(child=>{const room=child.val()||{};if(room.active===false)return;const unread=Number(unreadRooms[child.key]||0),card=document.createElement('button');card.type='button';card.className='room-card'+(child.key===currentRoomId&&currentView.type==='public'?' active':'');card.innerHTML='<div class="room-avatar">#</div><div class="room-meta"><strong></strong><small></small></div><span class="room-unread-badge hidden"></span>';card.querySelector('strong').textContent=room.name||child.key;card.querySelector('small').textContent=child.key===currentRoomId?onlineUserIds.size+' anggota online':'Buka grup chat';const badge=card.querySelector('.room-unread-badge');badge.textContent=unread>99?'99+':String(unread);badge.classList.toggle('hidden',unread===0);badge.setAttribute('aria-label',unread+' pesan belum dibaca');card.onclick=()=>switchGroupRoom(child.key,room.name||child.key,room.active!==false);list.appendChild(card)});if(!list.children.length)list.innerHTML='<div class="contact-empty">Belum ada room aktif.</div>'}
async function switchGroupRoom(id,name,active){if(id===currentRoomId)return openPublicChat();if(!active)return showToast('Room sedang nonaktif.');try{if(!isAdmin()){const code=prompt('Masukkan kode untuk room '+safeText(name)+':');if(code===null)return;const matched=await resolveRoomByCode(code.trim());if(!matched||matched.id!==id)return showToast('Kode room tidak cocok.')}if(refs.presence)await refs.presence.remove();cleanupSession();currentRoomId=id;currentRoomName=name;user.roomId=id;user.roomName=name;localStorage.setItem('nusa_chat_user',JSON.stringify(user));await startChat();closeSidebar();showToast('Berpindah ke '+safeText(name)+'.')}catch(err){showToast(err.message||'Gagal berpindah room.')}}
async function updateAdminCode(){if(!isAdmin())return;const current=$('currentAdminCode').value,next=$('newAdminCode').value,confirmCode=$('confirmAdminCode').value;if(!current)return showToast('Masukkan kode admin saat ini.');if(await sha256(current)!==await getAdminCodeHash())return showToast('Kode admin saat ini salah.');if(next.length<8)return showToast('Kode admin baru minimal 8 karakter.');if(next!==confirmCode)return showToast('Ulangi kode admin baru belum sama.');if(current===next)return showToast('Kode admin baru harus berbeda.');await db.ref('appConfig/adminCodeHash').set(await sha256(next));$('currentAdminCode').value='';$('newAdminCode').value='';$('confirmAdminCode').value='';addAdminLog('Mengganti kode rahasia admin setelah verifikasi');showToast('Kode admin berhasil diperbarui.')}
async function createAccountFromAdmin(){
  if(!isAdmin())return showToast('Fitur ini hanya untuk admin.');
  const button=$('createAccountBtn'),status=$('createAccountStatus'),username=$('adminNewUsername').value.trim(),password=$('adminNewPassword').value,confirmation=$('adminNewPasswordConfirm').value;
  const setStatus=(message,isError=true)=>{if(status){status.textContent=message;status.style.color=isError?'#ff91a4':'var(--success)'}showToast(message)};
  status.textContent='';
  if(username.toLowerCase()===ADMIN_NAME)return setStatus('Username admin tidak dapat dipakai.');
  if(!/^[A-Za-z0-9_.-]{3,24}$/.test(username))return setStatus('Username 3–24 karakter: huruf, angka, titik, garis bawah, atau strip.');
  if(password.length<6)return setStatus('Password minimal 6 karakter.');
  if(password!==confirmation)return setStatus('Konfirmasi password tidak sama.');
  button.disabled=true;button.textContent='Membuat...';setStatus('Sedang membuat akun...',false);
  try{
    const id=accountId(username),accountRef=db.ref('appConfig/accounts/'+id);
    const salt=makeSalt(),passwordHash=await hashPassword(password,salt);
    const payload={accountId:id,username,usernameLower:username.toLowerCase(),roomId:currentRoomId||DEFAULT_ROOM_ID,roomName:currentRoomName||DEFAULT_ROOM_NAME,passwordHash,salt,status:'approved',createdAt:firebase.database.ServerValue.TIMESTAMP,approvedAt:firebase.database.ServerValue.TIMESTAMP,approvedBy:user.name,createdByAdmin:true};
    const result=await accountRef.transaction(existing=>existing===null?payload:undefined);
    if(!result.committed)return setStatus('Username sudah terdaftar.');
    $('adminNewUsername').value='';$('adminNewPassword').value='';$('adminNewPasswordConfirm').value='';
    addAdminLog('Membuat akun '+safeText(username));
    setStatus('Akun '+safeText(username)+' berhasil dibuat dan langsung aktif.',false);
    await refreshAdminPanel();
  }catch(err){
    console.error('Gagal membuat akun dari panel admin:',err);
    const denied=err?.code==='PERMISSION_DENIED'||err?.code==='permission_denied';
    setStatus(denied?'Firebase Rules menolak pembuatan akun. Publish database.rules.json terbaru.':'Akun gagal dibuat: '+safeText(err?.message||err?.code||'kesalahan tidak diketahui'));
  }finally{
    button.disabled=false;button.textContent='Buat akun';
  }
}
async function changeUserPassword(id,name){
  if(!isAdmin())return showToast('Fitur ini hanya untuk admin.');
  const adminPassword=prompt('Masukkan password admin untuk mengubah password '+safeText(name)+':');
  if(adminPassword===null)return;
  if(!adminPassword||await sha256(adminPassword)!==await getAdminCodeHash())return showToast('Password admin salah.');
  const next=prompt('Masukkan password baru untuk '+safeText(name)+' (minimal 6 karakter):');
  if(next===null)return;
  if(next.length<6)return showToast('Password baru minimal 6 karakter.');
  const confirmation=prompt('Ulangi password baru untuk '+safeText(name)+':');
  if(confirmation===null)return;
  if(next!==confirmation)return showToast('Konfirmasi password baru tidak sama.');
  const accountRef=db.ref('appConfig/accounts/'+id),accountSnap=await accountRef.once('value');
  if(!accountSnap.exists())return showToast('Data akun tidak ditemukan.');
  const salt=makeSalt(),passwordHash=await hashPassword(next,salt);
  await accountRef.update({salt,passwordHash,passwordChangedAt:firebase.database.ServerValue.TIMESTAMP});
  const roomsSnap=await db.ref('appConfig/rooms').once('value'),jobs=[];
  roomsSnap.forEach(room=>{
    jobs.push(db.ref('rooms/'+room.key+'/presence').once('value').then(presence=>{
      const roomJobs=[];
      presence.forEach(session=>{const value=session.val()||{};if(value.userId===id)roomJobs.push(db.ref('rooms/'+room.key+'/kicks/'+session.key).set({reason:'Password akunmu telah diubah admin. Silakan login kembali.',by:user.name,at:firebase.database.ServerValue.TIMESTAMP}))});
      return Promise.all(roomJobs);
    }));
  });
  await Promise.all(jobs);
  addAdminLog('Mengubah password akun '+safeText(name));
  showToast('Password '+safeText(name)+' berhasil diubah. Semua sesinya dikeluarkan.');
}
async function kickAllSessions(id,name){const snap=await db.ref('rooms/'+currentRoomId+'/presence').once('value');const jobs=[];snap.forEach(x=>{const v=x.val();if(v?.userId===id)jobs.push(db.ref('rooms/'+currentRoomId+'/kicks/'+x.key).set({reason:'Kamu dikeluarkan dari ruang oleh admin.',by:user.name,at:firebase.database.ServerValue.TIMESTAMP}))});await Promise.all(jobs);addAdminLog('Kick '+safeText(name));showToast(jobs.length?'Pengguna berhasil dikeluarkan.':'Pengguna sedang offline.');refreshAdminPanel()}
async function toggleBan(id,name,isBanned){const ref=db.ref('rooms/'+currentRoomId+'/bannedUsers/'+id);if(isBanned){await ref.remove();addAdminLog('Membuka blokir '+safeText(name))}else{await ref.set({name,by:user.name,at:firebase.database.ServerValue.TIMESTAMP});await kickAllSessions(id,name);addAdminLog('Memblokir '+safeText(name))}refreshAdminPanel()}
async function purgeUser(id,name){return deleteAccountsWithVerification([id],'akun '+safeText(name))}
async function saveAdminSettings(){const next={maintenance:$('maintenanceToggle').checked,allowImages:$('imagesToggle').checked,ttlHours:Number($('ttlSelect').value)||24,maxLength:Math.max(100,Math.min(3000,Number($('maxLengthInput').value)||1000))};await db.ref('rooms/'+currentRoomId+'/settings').set(next);addAdminLog('Memperbarui pengaturan room');showToast('Pengaturan berhasil disimpan.')}
async function adminClear(path,label){if(!confirm(label+'? Tindakan ini tidak dapat dibatalkan.'))return;await db.ref('rooms/'+currentRoomId+'/'+path).remove();addAdminLog(label);showToast('Data berhasil dibersihkan.');refreshAdminPanel()}
function renderMembers(snap){els.membersList.innerHTML='';snap.forEach(child=>{const member=child.val();if(!member?.name)return;const item=document.createElement('div');item.className='member-item';const avatar=document.createElement('div');avatar.className='avatar';avatar.textContent=initials(member.name);const name=document.createElement('div');name.className='member-name';name.textContent=member.name+(child.key===encodeURIComponent(user.sessionId)?' (kamu)':'');item.append(avatar,name);if(child.key!==encodeURIComponent(user.sessionId)){const kick=document.createElement('button');kick.className='kick-btn';kick.type='button';kick.textContent='Kick';kick.onclick=()=>kickMember(child.key,member.name);item.appendChild(kick)}els.membersList.appendChild(item)});if(!els.membersList.children.length)els.membersList.textContent='Belum ada pengguna online.'}
async function kickMember(sessionKey,name){if(!isAdmin())return showToast('Fitur ini hanya untuk admin.');if(!confirm(`Keluarkan ${safeText(name)} dari ruang?`))return;try{await db.ref(`rooms/${currentRoomId}/kicks/${sessionKey}`).set({reason:`Kamu dikeluarkan dari ruang oleh admin.`,by:user.name,at:firebase.database.ServerValue.TIMESTAMP});showToast(`${safeText(name)} berhasil dikeluarkan.`)}catch{showToast('Pengguna gagal dikeluarkan. Periksa Firebase Rules.')}}
function messageActionButton(label,onClick){const btn=document.createElement('button');btn.className='message-action';btn.type='button';btn.textContent=label;btn.onclick=onClick;return btn}
async function deleteMessage(id){if(!confirm('Hapus pesan ini?'))return;try{await refs.messages.child(id).remove()}catch{showToast('Pesan gagal dihapus. Periksa izin database.')}}
async function editMessage(id,data){if(data.type!=='text')return showToast('Hanya pesan teks yang bisa diedit.');const next=prompt('Edit pesan:',safeText(data.text));if(next===null)return;const text=next.trim();if(!text)return showToast('Pesan tidak boleh kosong.');if(text.length>1000)return showToast('Pesan maksimal 1000 karakter.');try{await refs.messages.child(id).update({text,editedAt:firebase.database.ServerValue.TIMESTAMP,editedByAdmin:isAdmin()&&data.sessionId!==user.sessionId});showToast('Pesan berhasil diedit.')}catch{showToast('Pesan gagal diedit. Periksa izin database.')}}
function renderMessage(id,data,notify=false){if(data.type==='system'){const age=Date.now()-Number(data.timestamp||0);if(!data.timestamp||age>15000)return;const el=document.createElement('div');el.className='system-msg';el.dataset.id=id;el.textContent=safeText(data.text);els.messages.appendChild(el);scrollBottom();setTimeout(()=>el.remove(),Math.max(1000,15000-age));return}const welcome=$('welcome');if(welcome)welcome.remove();
  const self=(data.senderId&&data.senderId===currentAccountId())||(!data.senderId&&data.userId===currentAccountId())||(!data.senderId&&!data.userId&&data.sessionId===user.sessionId);const canManage=self||isAdmin();const row=document.createElement('div');row.className=`message-row ${self?'self':''}`;row.dataset.id=id;if(!self){const avatar=document.createElement('div');avatar.className='mini-avatar';avatar.textContent=initials(data.name);row.appendChild(avatar)}const wrap=document.createElement('div');wrap.className='message-wrap';if(!self){const sender=document.createElement('div');sender.className='sender';sender.textContent=safeText(data.name);wrap.appendChild(sender)}const bubble=document.createElement('div');bubble.className='bubble';if(data.type==='image'&&typeof data.url==='string'&&data.url.startsWith('data:image/')){const img=document.createElement('img');img.src=data.url;img.alt='Foto dari '+safeText(data.name);img.loading='lazy';img.addEventListener('click',()=>window.open(data.url,'_blank','noopener'));bubble.appendChild(img)}else{bubble.appendChild(document.createTextNode(safeText(data.text)))}const foot=document.createElement('div');foot.className='message-foot';const time=document.createElement('span');time.textContent=formatTime(data.timestamp);foot.appendChild(time);if(data.editedAt){const edited=document.createElement('span');edited.className='edited-label';edited.textContent=data.editedByAdmin?'diedit admin':'diedit';foot.appendChild(edited)}if(canManage&&data.type==='text')foot.appendChild(messageActionButton('edit',()=>editMessage(id,data)));if(canManage)foot.appendChild(messageActionButton('hapus',()=>deleteMessage(id)));bubble.appendChild(foot);wrap.appendChild(bubble);row.appendChild(wrap);els.messages.appendChild(row);scrollBottom();if(notify&&!self){notifyIncoming(data.name,data.type==='image'?'📷 Foto':data.text,currentView.type==='private');if(currentView.type==='public'&&document.hidden)showToast(`Pesan baru dari ${safeText(data.name)}`)}}
function playSound(isPrivate=false){
  try{
    const AudioCtx=window.AudioContext||window.webkitAudioContext;
    if(!AudioCtx)return;
    const ctx=playSound.ctx||(playSound.ctx=new AudioCtx());
    if(ctx.state==='suspended')ctx.resume().catch(()=>{});
    const start=ctx.currentTime+.01;
    const tones=isPrivate
      ?[{frequency:880,offset:0,duration:.13,volume:.055},{frequency:1175,offset:.17,duration:.18,volume:.065}]
      :[{frequency:620,offset:0,duration:.16,volume:.04}];
    tones.forEach(tone=>{
      const oscillator=ctx.createOscillator(),gain=ctx.createGain();
      oscillator.type=isPrivate?'sine':'triangle';
      oscillator.frequency.setValueAtTime(tone.frequency,start+tone.offset);
      gain.gain.setValueAtTime(.0001,start+tone.offset);
      gain.gain.exponentialRampToValueAtTime(tone.volume,start+tone.offset+.018);
      gain.gain.exponentialRampToValueAtTime(.0001,start+tone.offset+tone.duration);
      oscillator.connect(gain);gain.connect(ctx.destination);
      oscillator.start(start+tone.offset);
      oscillator.stop(start+tone.offset+tone.duration+.02);
    });
  }catch{}
}
async function send(){if(!user)return;const text=els.messageInput.value.trim();if(!text&&!pendingImage)return;if(pendingImage&&appSettings.allowImages===false)return showToast('Pengiriman foto dinonaktifkan admin.');const maxLength=Math.max(100,Math.min(3000,Number(appSettings.maxLength)||1000));if(text.length>maxLength)return showToast('Pesan maksimal '+maxLength+' karakter.');els.sendBtn.disabled=true;try{const payload={name:user.name,userId:currentAccountId(),senderId:currentAccountId(),privateTo:currentView.type==='private'?currentView.peer.id:null,sessionId:user.sessionId,timestamp:firebase.database.ServerValue.TIMESTAMP,type:pendingImage?'image':'text'};if(pendingImage)payload.url=pendingImage.data;else payload.text=text;await refs.messages.push(payload);els.messageInput.value='';els.messageInput.style.height='auto';cancelPendingImage();await refs.typing.remove();resetIdle()}catch{showToast('Pesan gagal terkirim. Periksa koneksi.')}finally{els.sendBtn.disabled=false;els.messageInput.focus()}}
function cancelPendingImage(){pendingImage=null;els.fileInput.value='';els.imagePreview.classList.add('hidden');els.previewImg.removeAttribute('src')}
function cleanupSession(){inboxLatest={};inboxReady=false;clearChatListeners();clearRoomInboxListeners();cleanup.splice(0).forEach(fn=>{try{fn()}catch{}});clearTimeout(idleTimer);clearInterval(cleanupTimer);cleanupTimer=null;clearTimeout(typingTimer);if(refs.typing)refs.typing.remove().catch(()=>{});refs={}}
async function logout(reason='Kamu sudah keluar dari ruang.'){if(isLoggingOut)return;isLoggingOut=true;try{if(refs.presence)await refs.presence.remove();if(refs.typing)await refs.typing.remove();await releaseActiveSession()}catch{}cleanupSession();unreadPrivate={};unreadRooms={};roomLastRead={};updateDocumentTitle();closeSidebar();localStorage.removeItem('nusa_chat_user');user=null;els.chatApp.classList.add('hidden');els.loginPage.classList.remove('hidden');els.inputPassword.value='';els.inputRoomCode.value='';els.inputAdminCode.value='';els.adminCodeField.classList.add('hidden');$('clearChatBtn').classList.add('hidden');$('membersBtn').classList.add('hidden');$('adminPanelBtn').classList.add('hidden');$('adminPendingBadge').classList.add('hidden');$('adminOverlay').classList.add('hidden');els.membersPanel.classList.add('hidden');clearSessionUI();setConnected(false);showToast(reason);isLoggingOut=false}
