$('photoBtn').addEventListener('click',()=>els.fileInput.click());els.fileInput.addEventListener('change',()=>{const file=els.fileInput.files[0];if(!file)return;if(file.size>MAX_IMAGE_BYTES){cancelPendingImage();return showToast('Ukuran foto maksimal 2 MB.')}if(!/^image\/(jpeg|png|webp)$/.test(file.type)){cancelPendingImage();return showToast('Gunakan foto JPG, PNG, atau WebP.')}const reader=new FileReader();reader.onload=()=>{pendingImage={data:reader.result,name:file.name};els.previewImg.src=reader.result;els.previewName.textContent=file.name;els.imagePreview.classList.remove('hidden')};reader.readAsDataURL(file)});$('cancelImage').addEventListener('click',cancelPendingImage);
