(async()=>{try{const saved=JSON.parse(localStorage.getItem('nusa_chat_user'));if(saved?.name&&saved?.roomId&&saved?.accountId&&saved?.isAdmin!==true){const account=(await db.ref('appConfig/accounts/'+saved.accountId).once('value')).val();if(account?.status!=='approved')throw new Error('inactive');if(!await claimActiveSession(saved.accountId,saved.sessionId,saved.name))throw new Error('Akun aktif di perangkat lain.');currentRoomId=saved.roomId;currentRoomName=saved.roomName||DEFAULT_ROOM_NAME;user=saved;els.loginPage.classList.add('hidden');els.chatApp.classList.remove('hidden');$('userName').textContent=user.name;$('userAvatar').textContent=initials(user.name);await startChat()}else localStorage.removeItem('nusa_chat_user')}catch{localStorage.removeItem('nusa_chat_user')}})();
